// vault: spending is allowed only when the redeemer says the
// magic word AND the transaction is signed by the owner from the
// datum. `aiken check` runs the tests below - no node, no keys.
use cardano/transaction.{OutputReference, Transaction}
use aiken/collection/list

pub type Datum {
  owner: ByteArray,
}

pub type Redeemer {
  msg: ByteArray,
}

validator vault {
  spend(
    datum: Option<Datum>,
    redeemer: Redeemer,
    _own_ref: OutputReference,
    self: Transaction,
  ) {
    expect Some(d) = datum
    let says_open = redeemer.msg == "open"
    let owner_signed = list.has(self.extra_signatories, d.owner)
    says_open && owner_signed
  }

  else(_) {
    fail
  }
}

