// Counter: anyone may increment, only the deployer may reset.
contract Counter {
    owner: Address;
    val: Int as uint32;

    init() {
        self.owner = sender();
        self.val = 0;
    }

    receive("increment") {
        self.val = self.val + 1;
    }

    receive("reset") {
        require(sender() == self.owner, "owner only");
        self.val = 0;
    }

    get fun value(): Int {
        return self.val;
    }
}

